package com.nendarolas.inventoryvalue;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

class InventoryItemValueOverlay extends WidgetItemOverlay
{
	private static final Color SHADOW = new Color(0, 0, 0, 180);

	private final NendaRolasInventoryValueConfig config;
	private final PriceService priceService;
	private final ValueColorResolver valueColorResolver;
	private final InventorySlotResolver slotResolver;
	private final InventorySlotExclusions slotExclusions;

	@Inject
	InventoryItemValueOverlay(
		NendaRolasInventoryValueConfig config,
		PriceService priceService,
		ValueColorResolver valueColorResolver,
		InventorySlotResolver slotResolver,
		InventorySlotExclusions slotExclusions)
	{
		this.config = config;
		this.priceService = priceService;
		this.valueColorResolver = valueColorResolver;
		this.slotResolver = slotResolver;
		this.slotExclusions = slotExclusions;
		showOnInterfaces(net.runelite.api.gameval.InterfaceID.INVENTORY);
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (slotExclusions.isExcluded(slotResolver.getSlot(widgetItem)))
		{
			return;
		}

		if (!priceService.isGeTradeable(itemId))
		{
			if (config.showUntradeable())
			{
				drawLabel(graphics, widgetItem, config.untradeableLabel(), config.untradeableColor());
			}
			return;
		}

		final long value = priceService.getValue(itemId, widgetItem.getQuantity(), config.showStackValue());
		if (value < config.minimumValue())
		{
			return;
		}

		drawLabel(graphics, widgetItem, ValueFormatter.format(value), valueColorResolver.getColor(value));
	}

	private void drawLabel(Graphics2D graphics, WidgetItem widgetItem, String text, Color color)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}

		final Rectangle bounds = widgetItem.getCanvasBounds();
		final Font originalFont = graphics.getFont();
		final Font font = originalFont.deriveFont(Font.BOLD, config.textSize());

		graphics.setFont(font);
		final FontMetrics metrics = graphics.getFontMetrics();
		final int x = bounds.x + (bounds.width - metrics.stringWidth(text)) / 2;
		final int y = bounds.y + bounds.height - 2;

		graphics.setColor(SHADOW);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(color);
		graphics.drawString(text, x, y);
		graphics.setFont(originalFont);
	}
}

package com.nendarolas.inventoryvalue;

import javax.inject.Inject;

class InventorySlotExclusions
{
	private static final int MIN_SLOT = 1;
	private static final int MAX_SLOT = 28;

	private final NendaRolasInventoryValueConfig config;

	@Inject
	InventorySlotExclusions(NendaRolasInventoryValueConfig config)
	{
		this.config = config;
	}

	boolean isExcluded(int slot)
	{
		if (slot < MIN_SLOT || slot > MAX_SLOT)
		{
			return false;
		}

		final String excludedSlots = config.excludedSlots();
		if (excludedSlots == null || excludedSlots.trim().isEmpty())
		{
			return false;
		}

		for (String part : excludedSlots.split(","))
		{
			if (matchesPart(slot, part.trim()))
			{
				return true;
			}
		}

		return false;
	}

	private boolean matchesPart(int slot, String part)
	{
		if (part.isEmpty())
		{
			return false;
		}

		final int dash = part.indexOf('-');
		if (dash >= 0)
		{
			final Integer start = parseSlot(part.substring(0, dash));
			final Integer end = parseSlot(part.substring(dash + 1));
			if (start == null || end == null)
			{
				return false;
			}

			return slot >= Math.min(start, end) && slot <= Math.max(start, end);
		}

		final Integer singleSlot = parseSlot(part);
		return singleSlot != null && slot == singleSlot;
	}

	private Integer parseSlot(String value)
	{
		try
		{
			final int slot = Integer.parseInt(value.trim());
			return slot >= MIN_SLOT && slot <= MAX_SLOT ? slot : null;
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.nendarolas.inventoryvalue;

import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;

class InventorySlotResolver
{
	private static final int COLUMNS = 4;
	private static final int ROWS = 7;

	private final Client client;

	@Inject
	InventorySlotResolver(Client client)
	{
		this.client = client;
	}

	int getSlot(WidgetItem widgetItem)
	{
		final int widgetSlot = getSlot(widgetItem.getWidget());
		if (widgetSlot != -1)
		{
			return widgetSlot;
		}

		final Widget inventory = client.getWidget(InterfaceID.Inventory.ITEMS);
		if (inventory == null)
		{
			return -1;
		}

		final Rectangle inventoryBounds = inventory.getBounds();
		final Rectangle itemBounds = widgetItem.getCanvasBounds();
		if (inventoryBounds == null || itemBounds == null || inventoryBounds.width <= 0 || inventoryBounds.height <= 0)
		{
			return -1;
		}

		final int centerX = itemBounds.x + itemBounds.width / 2;
		final int centerY = itemBounds.y + itemBounds.height / 2;
		final int col = clamp((centerX - inventoryBounds.x) * COLUMNS / inventoryBounds.width, 0, COLUMNS - 1);
		final int row = clamp((centerY - inventoryBounds.y) * ROWS / inventoryBounds.height, 0, ROWS - 1);
		return row * COLUMNS + col + 1;
	}

	int getSlot(Widget widget)
	{
		if (widget == null)
		{
			return -1;
		}

		final int widgetIndex = widget.getIndex();
		return widgetIndex >= 0 && widgetIndex < COLUMNS * ROWS ? widgetIndex + 1 : -1;
	}

	private int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}
}

package com.nendarolas.inventoryvalue;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class InventoryTotalValueOverlay extends Overlay
{
	private static final Color BACKGROUND = new Color(0, 0, 0, 150);
	private static final Color SHADOW = new Color(0, 0, 0, 190);
	private static final int[] INVENTORY_ICONS = {
		InterfaceID.Toplevel.ICON3,
		InterfaceID.ToplevelOsrsStretch.ICON3,
		InterfaceID.ToplevelPreEoc.ICON3
	};
	private static final int PADDING_X = 4;
	private static final int PADDING_Y = 2;

	private final Client client;
	private final NendaRolasInventoryValueConfig config;
	private final PriceService priceService;
	private final ValueColorResolver valueColorResolver;
	private final InventorySlotExclusions slotExclusions;

	@Inject
	InventoryTotalValueOverlay(
		Client client,
		NendaRolasInventoryValueConfig config,
		PriceService priceService,
		ValueColorResolver valueColorResolver,
		InventorySlotExclusions slotExclusions)
	{
		this.client = client;
		this.config = config;
		this.priceService = priceService;
		this.valueColorResolver = valueColorResolver;
		this.slotExclusions = slotExclusions;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showTotal())
		{
			return null;
		}

		final Widget inventoryIcon = getVisibleInventoryIcon();
		if (inventoryIcon == null)
		{
			return null;
		}

		final ItemContainer inventoryContainer = client.getItemContainer(InventoryID.INV);
		if (inventoryContainer == null)
		{
			return null;
		}

		long total = 0;
		final Item[] items = inventoryContainer.getItems();
		for (int i = 0; i < items.length; i++)
		{
			if (!slotExclusions.isExcluded(i + 1))
			{
				total += priceService.getValue(items[i], true);
			}
		}

		final String text = ValueFormatter.format(total);
		final Font originalFont = graphics.getFont();
		final Rectangle bounds = inventoryIcon.getBounds();
		Font font = originalFont.deriveFont(Font.BOLD, Math.max(8, config.textSize()));
		graphics.setFont(font);

		FontMetrics metrics = graphics.getFontMetrics();
		while (metrics.stringWidth(text) + PADDING_X * 2 > bounds.width + 12 && font.getSize() > 8)
		{
			font = font.deriveFont((float) font.getSize() - 1);
			graphics.setFont(font);
			metrics = graphics.getFontMetrics();
		}

		final int width = Math.min(bounds.width + 12, metrics.stringWidth(text) + PADDING_X * 2);
		final int height = metrics.getHeight() + PADDING_Y * 2;
		final int x = bounds.x + (bounds.width - width) / 2;
		final int y = bounds.y + bounds.height - height + 2;
		final int textX = x + (width - metrics.stringWidth(text)) / 2;
		final int textY = y + PADDING_Y + metrics.getAscent();

		graphics.setColor(BACKGROUND);
		graphics.fillRoundRect(x, y, width, height, 6, 6);
		graphics.setColor(SHADOW);
		graphics.drawString(text, textX + 1, textY + 1);
		graphics.setColor(valueColorResolver.getColor(total));
		graphics.drawString(text, textX, textY);
		graphics.setFont(originalFont);

		return new Dimension(width, height);
	}

	private Widget getVisibleInventoryIcon()
	{
		for (int componentId : INVENTORY_ICONS)
		{
			final Widget widget = client.getWidget(componentId);
			if (widget != null && !widget.isHidden())
			{
				final Rectangle bounds = widget.getBounds();
				if (bounds != null && bounds.width > 0 && bounds.height > 0)
				{
					return widget;
				}
			}
		}

		return null;
	}
}

package com.nendarolas.inventoryvalue;

import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

class InventoryValueTooltip
{
	private static final Color TOOLTIP_TEXT = new Color(238, 238, 238);

	private final Client client;
	private final NendaRolasInventoryValueConfig config;
	private final PriceService priceService;
	private final InventorySlotResolver slotResolver;
	private final InventorySlotExclusions slotExclusions;
	private final TooltipManager tooltipManager;

	@Inject
	InventoryValueTooltip(
		Client client,
		NendaRolasInventoryValueConfig config,
		PriceService priceService,
		InventorySlotResolver slotResolver,
		InventorySlotExclusions slotExclusions,
		TooltipManager tooltipManager)
	{
		this.client = client;
		this.config = config;
		this.priceService = priceService;
		this.slotResolver = slotResolver;
		this.slotExclusions = slotExclusions;
		this.tooltipManager = tooltipManager;
	}

	void addTooltip()
	{
		if (!config.showTooltipValue() || client.isMenuOpen())
		{
			return;
		}

		final MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
		if (menuEntries.length == 0)
		{
			return;
		}

		final MenuEntry menuEntry = menuEntries[menuEntries.length - 1];
		final Widget widget = menuEntry.getWidget();
		if (widget == null || menuEntry.getParam1() != InterfaceID.Inventory.ITEMS)
		{
			return;
		}

		final int slot = slotResolver.getSlot(widget);
		if (slotExclusions.isExcluded(slot))
		{
			return;
		}

		final int itemId = widget.getItemId();
		final int quantity = widget.getItemQuantity();
		final String tooltip = buildTooltip(itemId, quantity);
		if (tooltip != null)
		{
			tooltipManager.add(new Tooltip(ColorUtil.prependColorTag(tooltip, TOOLTIP_TEXT)));
		}
	}

	private String buildTooltip(int itemId, int quantity)
	{
		if (itemId <= 0)
		{
			return null;
		}

		if (!priceService.isGeTradeable(itemId))
		{
			return config.showUntradeable() ? "GE value: " + config.untradeableLabel() : null;
		}

		final long unitValue = priceService.getValue(itemId, 1, false);
		final long stackValue = priceService.getValue(itemId, quantity, true);
		if (stackValue <= 0)
		{
			return null;
		}

		if (quantity > 1)
		{
			return "GE value: " + ValueFormatter.format(stackValue) + " (unit: " + ValueFormatter.format(unitValue) + ")";
		}

		return "GE value: " + ValueFormatter.format(unitValue);
	}
}

