package com.nendarolas.inventoryvalue;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.events.BeforeRender;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "NendaRolas Inventory Value",
	description = "Shows Grand Exchange values on inventory items and a total inventory value",
	tags = {"ge", "grand exchange", "inventory", "items", "price", "value"}
)
public class NendaRolasInventoryValuePlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private InventoryItemValueOverlay itemValueOverlay;

	@Inject
	private InventoryTotalValueOverlay totalValueOverlay;

	@Inject
	private InventoryValueTooltip inventoryValueTooltip;

	@Override
	protected void startUp()
	{
		overlayManager.add(itemValueOverlay);
		overlayManager.add(totalValueOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(itemValueOverlay);
		overlayManager.remove(totalValueOverlay);
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		inventoryValueTooltip.addTooltip();
	}

	@Provides
	NendaRolasInventoryValueConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NendaRolasInventoryValueConfig.class);
	}
}

package com.nendarolas.inventoryvalue;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

@Singleton
class PriceService
{
	@Inject
	private ItemManager itemManager;

	long getUnitPrice(int itemId)
	{
		if (itemId <= 0)
		{
			return 0;
		}

		final int canonicalId = getCanonicalItemId(itemId);
		if (!isGeTradeable(canonicalId))
		{
			return 0;
		}

		return Math.max(0L, itemManager.getItemPrice(canonicalId));
	}

	boolean isGeTradeable(int itemId)
	{
		if (itemId <= 0)
		{
			return false;
		}

		return itemManager.getItemComposition(getCanonicalItemId(itemId)).isGeTradeable();
	}

	long getValue(Item item, boolean stackValue)
	{
		if (item == null || item.getId() <= 0)
		{
			return 0;
		}

		return getValue(item.getId(), item.getQuantity(), stackValue);
	}

	long getValue(int itemId, int quantity, boolean stackValue)
	{
		if (itemId <= 0)
		{
			return 0;
		}

		final long price = getUnitPrice(itemId);
		if (price <= 0)
		{
			return 0;
		}

		return stackValue ? price * Math.max(1, quantity) : price;
	}

	private int getCanonicalItemId(int itemId)
	{
		final ItemComposition composition = itemManager.getItemComposition(itemId);
		return composition.getNote() != -1 ? composition.getLinkedNoteId() : itemId;
	}
}

package com.nendarolas.inventoryvalue;

import java.awt.Color;
import javax.inject.Inject;

class ValueColorResolver
{
	private final NendaRolasInventoryValueConfig config;

	@Inject
	ValueColorResolver(NendaRolasInventoryValueConfig config)
	{
		this.config = config;
	}

	Color getColor(long value)
	{
		if (value < config.tierOneLimit())
		{
			return config.tierOneColor();
		}

		if (value < config.tierTwoLimit())
		{
			return config.tierTwoColor();
		}

		if (value < config.tierThreeLimit())
		{
			return config.tierThreeColor();
		}

		if (value < config.tierFourLimit())
		{
			return config.tierFourColor();
		}

		return config.tierFiveColor();
	}
}

package com.nendarolas.inventoryvalue;

import java.util.Locale;

final class ValueFormatter
{
	private ValueFormatter()
	{
	}

	static String format(long value)
	{
		if (value >= 1_000_000_000L)
		{
			return trim(value / 1_000_000_000.0) + "B";
		}

		if (value >= 1_000_000L)
		{
			return trim(value / 1_000_000.0) + "M";
		}

		if (value >= 1_000L)
		{
			return trim(value / 1_000.0) + "K";
		}

		return Long.toString(value);
	}

	private static String trim(double value)
	{
		final String formatted = value >= 10
			? String.format(Locale.ROOT, "%.0f", value)
			: String.format(Locale.ROOT, "%.1f", value);
		return formatted.endsWith(".0") ? formatted.substring(0, formatted.length() - 2) : formatted;
	}
}

